def read(n):return json.loads((ROOT/n).read_text())
def main():
 audit=read('final_readback_audit.json');account=read('effective_all_record_accounting.json');scope=read('semantic_review_scope.json');cost=read('cost_and_attempt_accounting.json');before=read('db_before.json');after=audit['db_counts'];review=read('semantic_review.json');rows=read('canonical_results.json');sem=audit['personal_review_decisions'];tests=read('test_report.json')
 (ROOT/'db_current_readback.json').write_text(json.dumps({k:after[k] for k in before},ensure_ascii=False,indent=2)+'\n')
